// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;

interface IEntropy {
    function getRandomNumber(
        bytes32 sequenceNumber
    ) external returns (bytes32 randomNumber);

    function request(
        address provider,
        bytes32 userCommitment,
        bool useBlockHash
    ) external payable returns (uint64 sequenceNumber);

    function getFee(address provider) external view returns (uint256 feeAmount);

    function getDefaultProvider() external view returns (address);
}

interface IEntropyConsumer {
    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomNumber
    ) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./IEntropy.sol";

contract CoinFlip is IEntropyConsumer {
    IEntropy private entropy;
    address private entropyProvider;

    struct Game {
        address player;
        uint256 betAmount;
        bool guess; // true = heads, false = tails
        bool active;
    }

    mapping(uint64 => Game) public games;
    mapping(address => uint256) public wins;
    mapping(address => uint256) public losses;

    event GameStarted(uint64 indexed sequenceNumber, address indexed player, uint256 betAmount, bool guess);
    event GameResult(uint64 indexed sequenceNumber, address indexed player, bool won, bool result, uint256 payout);

    constructor(address _entropy, address _entropyProvider) {
        entropy = IEntropy(_entropy);
        entropyProvider = _entropyProvider;
    }

    function flip(bool _guess) external payable {
        require(msg.value > 0, "Bet amount must be greater than 0");
        require(address(this).balance >= msg.value * 2, "Insufficient contract balance");

        // Get entropy fee
        uint256 fee = entropy.getFee(entropyProvider);
        require(msg.value > fee, "Bet must cover entropy fee");

        // Request random number
        bytes32 userCommitment = keccak256(abi.encodePacked(msg.sender, block.timestamp));
        uint64 sequenceNumber = entropy.request{value: fee}(entropyProvider, userCommitment, false);

        // Store game
        games[sequenceNumber] = Game({
            player: msg.sender,
            betAmount: msg.value - fee,
            guess: _guess,
            active: true
        });

        emit GameStarted(sequenceNumber, msg.sender, msg.value - fee, _guess);
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomNumber
    ) external override {
        require(msg.sender == address(entropy), "Only entropy contract can call this");
        require(provider == entropyProvider, "Invalid provider");

        Game storage game = games[sequenceNumber];
        require(game.active, "Game not active");

        // Determine result (even = heads, odd = tails)
        bool result = (uint256(randomNumber) % 2) == 0;
        bool won = (result == game.guess);

        uint256 payout = 0;
        if (won) {
            payout = game.betAmount * 2;
            wins[game.player]++;
            payable(game.player).transfer(payout);
        } else {
            losses[game.player]++;
        }

        game.active = false;

        emit GameResult(sequenceNumber, game.player, won, result, payout);
    }

    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function getPlayerStats(address player) external view returns (uint256 winCount, uint256 lossCount) {
        return (wins[player], losses[player]);
    }

    // Allow contract to receive ETH
    receive() external payable {}

    // Emergency withdraw (only for contract owner)
    address public owner;

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this");
        _;
    }

    function setOwner(address _owner) external {
        require(owner == address(0), "Owner already set");
        owner = _owner;
    }

    function emergencyWithdraw() external onlyOwner {
        payable(owner).transfer(address(this).balance);
    }
}

