import { useState, useEffect } from 'react'
import { ethers } from 'ethers'
import './App.css'

// Contract ABI (simplified for the functions we need)
const COIN_FLIP_ABI = [
  "function flip(bool _guess) external payable",
  "function getContractBalance() external view returns (uint256)",
  "function getPlayerStats(address player) external view returns (uint256 winCount, uint256 lossCount)",
  "event GameStarted(uint64 indexed sequenceNumber, address indexed player, uint256 betAmount, bool guess)",
  "event GameResult(uint64 indexed sequenceNumber, address indexed player, bool won, bool result, uint256 payout)"
]

// We'll update this with the deployed contract address
const CONTRACT_ADDRESS = "0x0000000000000000000000000000000000000000" // TODO: Update after deployment

function App() {
  const [provider, setProvider] = useState(null)
  const [signer, setSigner] = useState(null)
  const [contract, setContract] = useState(null)
  const [account, setAccount] = useState('')
  const [betAmount, setBetAmount] = useState('0.01')
  const [loading, setLoading] = useState(false)
  const [gameHistory, setGameHistory] = useState([])
  const [stats, setStats] = useState({ wins: 0, losses: 0 })
  const [contractBalance, setContractBalance] = useState('0')

  useEffect(() => {
    if (typeof window.ethereum !== 'undefined') {
      const web3Provider = new ethers.BrowserProvider(window.ethereum)
      setProvider(web3Provider)
    }
  }, [])

  const connectWallet = async () => {
    if (!provider) {
      alert('Please install MetaMask!')
      return
    }

    try {
      await provider.send("eth_requestAccounts", [])
      const web3Signer = await provider.getSigner()
      const address = await web3Signer.getAddress()

      setSigner(web3Signer)
      setAccount(address)

      // Initialize contract
      if (CONTRACT_ADDRESS !== "0x0000000000000000000000000000000000000000") {
        const coinFlipContract = new ethers.Contract(CONTRACT_ADDRESS, COIN_FLIP_ABI, web3Signer)
        setContract(coinFlipContract)

        // Load stats and balance
        loadStats(coinFlipContract, address)
        loadContractBalance(coinFlipContract)

        // Listen for events
        setupEventListeners(coinFlipContract, address)
      }
    } catch (error) {
      console.error('Error connecting wallet:', error)
      alert('Failed to connect wallet')
    }
  }

  const loadStats = async (contractInstance, playerAddress) => {
    try {
      const [wins, losses] = await contractInstance.getPlayerStats(playerAddress)
      setStats({ wins: Number(wins), losses: Number(losses) })
    } catch (error) {
      console.error('Error loading stats:', error)
    }
  }

  const loadContractBalance = async (contractInstance) => {
    try {
      const balance = await contractInstance.getContractBalance()
      setContractBalance(ethers.formatEther(balance))
    } catch (error) {
      console.error('Error loading contract balance:', error)
    }
  }

  const setupEventListeners = (contractInstance, playerAddress) => {
    // Listen for game results
    contractInstance.on('GameResult', (sequenceNumber, player, won, result, payout, event) => {
      if (player.toLowerCase() === playerAddress.toLowerCase()) {
        const gameResult = {
          id: Number(sequenceNumber),
          won,
          result: result ? 'Heads' : 'Tails',
          payout: ethers.formatEther(payout),
          timestamp: new Date().toLocaleTimeString()
        }
        setGameHistory(prev => [gameResult, ...prev.slice(0, 9)]) // Keep last 10 games
        setLoading(false)

        // Update stats
        if (won) {
          setStats(prev => ({ ...prev, wins: prev.wins + 1 }))
        } else {
          setStats(prev => ({ ...prev, losses: prev.losses + 1 }))
        }

        // Update contract balance
        loadContractBalance(contractInstance)
      }
    })
  }

  const playGame = async (guess) => {
    if (!contract || !signer) {
      alert('Please connect your wallet first')
      return
    }

    if (parseFloat(betAmount) <= 0) {
      alert('Please enter a valid bet amount')
      return
    }

    setLoading(true)

    try {
      const betAmountWei = ethers.parseEther(betAmount)

      // Call flip function with bet amount
      const tx = await contract.flip(guess, { 
        value: betAmountWei,
        gasLimit: 300000 
      })

      await tx.wait()
      // Loading will be set to false when we receive the GameResult event

    } catch (error) {
      console.error('Error playing game:', error)
      setLoading(false)
      alert('Transaction failed: ' + error.message)
    }
  }

  const switchToBaseSepolia = async () => {
    try {
      await window.ethereum.request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: '0x14a34' }], // Base Sepolia chain ID
      })
    } catch (switchError) {
      if (switchError.code === 4902) {
        // Chain not added yet
        try {
          await window.ethereum.request({
            method: 'wallet_addEthereumChain',
            params: [{
              chainId: '0x14a34',
              chainName: 'Base Sepolia',
              nativeCurrency: {
                name: 'ETH',
                symbol: 'ETH',
                decimals: 18
              },
              rpcUrls: ['https://sepolia.base.org'],
              blockExplorerUrls: ['https://sepolia.basescan.org']
            }]
          })
        } catch (addError) {
          console.error('Error adding Base Sepolia:', addError)
        }
      }
    }
  }

  return (
    <div className="app">
      <header className="header">
        <h1>🪙 Coin Flip Game</h1>
        <p>Powered by Pyth Entropy - Verifiable Randomness</p>
      </header>

      <main className="main">
        {!account ? (
          <div className="connect-section">
            <button onClick={connectWallet} className="connect-btn">
              Connect Wallet
            </button>
            <p>Connect your wallet to start playing!</p>
          </div>
        ) : (
          <>
            <div className="account-info">
              <p><strong>Account:</strong> {account.slice(0, 6)}...{account.slice(-4)}</p>
              <p><strong>Stats:</strong> {stats.wins} wins, {stats.losses} losses</p>
              <p><strong>Contract Balance:</strong> {contractBalance} ETH</p>
              <button onClick={switchToBaseSepolia} className="network-btn">
                Switch to Base Sepolia
              </button>
            </div>

            <div className="game-section">
              <div className="bet-input">
                <label htmlFor="betAmount">Bet Amount (ETH):</label>
                <input
                  id="betAmount"
                  type="number"
                  step="0.001"
                  min="0"
                  value={betAmount}
                  onChange={(e) => setBetAmount(e.target.value)}
                  disabled={loading}
                />
              </div>

              <div className="game-buttons">
                <button
                  onClick={() => playGame(true)}
                  disabled={loading || CONTRACT_ADDRESS === "0x0000000000000000000000000000000000000000"}
                  className="heads-btn"
                >
                  {loading ? '🎲 Flipping...' : '👑 HEADS'}
                </button>
                <button
                  onClick={() => playGame(false)}
                  disabled={loading || CONTRACT_ADDRESS === "0x0000000000000000000000000000000000000000"}
                  className="tails-btn"
                >
                  {loading ? '🎲 Flipping...' : '🪙 TAILS'}
                </button>
              </div>

              {CONTRACT_ADDRESS === "0x0000000000000000000000000000000000000000" && (
                <p className="contract-warning">
                  ⚠️ Contract not deployed yet. Please wait for deployment.
                </p>
              )}

              <div className="rules">
                <h3>Game Rules:</h3>
                <ul>
                  <li>Choose your bet amount and pick heads or tails</li>
                  <li>Win: Get 2x your bet back!</li>
                  <li>Lose: Forfeit your bet</li>
                  <li>Results are generated using Pyth Entropy for fairness</li>
                </ul>
              </div>
            </div>

            {gameHistory.length > 0 && (
              <div className="history-section">
                <h3>Recent Games:</h3>
                <div className="history">
                  {gameHistory.map((game) => (
                    <div key={game.id} className={`game-result ${game.won ? 'win' : 'loss'}`}>
                      <span className="result">{game.result}</span>
                      <span className="outcome">{game.won ? '✅ WIN' : '❌ LOSS'}</span>
                      <span className="payout">
                        {game.won ? `+${game.payout} ETH` : `-${betAmount} ETH`}
                      </span>
                      <span className="time">{game.timestamp}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </>
        )}
      </main>
    </div>
  )
}

export default App

