  transition: border-color 0.2s;
}

.bet-input input:focus {
  outline: none;
  border-color: #667eea;
}

.game-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin-bottom: 2rem;
}

.heads-btn, .tails-btn {
  flex: 1;
  max-width: 200px;
  padding: 1.5rem;
  border: none;
  border-radius: 15px;
  font-size: 1.2rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.heads-btn {
  background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
