  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.contract-warning {
  text-align: center;
  color: #ff6b6b;
  font-weight: 600;
  margin: 1rem 0;
}

.rules {
  background: #f8f9fa;
  padding: 1.5rem;
  border-radius: 10px;
  margin-top: 1rem;
}

.rules h3 {
  margin-bottom: 1rem;
  color: #333;
}

.rules ul {
  padding-left: 1.5rem;
}

.rules li {
  margin: 0.5rem 0;
  color: #666;
}

.history-section {
  background: rgba(255, 255, 255, 0.95);
  padding: 2rem;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}

.history-section h3 {
  margin-bottom: 1rem;
  color: #333;
}

.history {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.game-result {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 1rem;
  padding: 1rem;
  border-radius: 10px;
  font-size: 0.9rem;
}

.game-result.win {
  background: linear-gradient(135deg, #d4fc79 0%, #96e6a1 100%);
}

.game-result.loss {
  background: linear-gradient(135deg, #ffecd2 0%, #fcb69f 100%);
}

.result {
  font-weight: 600;
}

.outcome {
  font-weight: 600;
}

.payout {
  font-weight: 600;
}

.time {
  color: #666;
  font-size: 0.8rem;
}

@media (max-width: 768px) {
  .header h1 {
    font-size: 2rem;
  }

  .main {
    padding: 1rem;
  }

  .game-buttons {
    flex-direction: column;
  }

  .game-result {
    grid-template-columns: 1fr;
    gap: 0.5rem;
    text-align: center;
  }
}

